CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_create_invoice` (IN `p_invoice_category` ENUM('sales','purchase'), IN `p_branch_id` INT, IN `p_source_type` VARCHAR(50), IN `p_source_id` INT, IN `p_customer_id` INT, IN `p_supplier_id` INT, IN `p_agent_id` INT, IN `p_branch_entity_id` INT, IN `p_currency_id` INT, IN `p_total_amount` DECIMAL(15,2), IN `p_discount` DECIMAL(15,2), IN `p_cost_amount` DECIMAL(15,2), IN `p_payment_type` ENUM('cash','credit','bank_transfer','agent','branch'), IN `p_description` TEXT, IN `p_created_by` INT, IN `p_cost_center_id` INT, INOUT `p_invoice_number` VARCHAR(50), OUT `p_invoice_id` INT)   BEGIN
        IF p_invoice_number IS NULL OR p_invoice_number = '' THEN
            SET p_invoice_number = fn_get_next_sequence('invoice');
        END IF;
        
            invoice_number, invoice_date, branch_id, invoice_category, source_type, source_id,
            customer_id, supplier_id, agent_id, branch_entity_id, cost_center_id, currency_id,
            total_amount, discount, cost_amount, payment_type, payment_status, invoice_status,
            description, created_by
        ) VALUES (
            p_invoice_number, CURDATE(), p_branch_id, p_invoice_category, p_source_type, p_source_id,
            p_customer_id, p_supplier_id, p_agent_id, p_branch_entity_id, p_cost_center_id, p_currency_id,
            p_total_amount, IFNULL(p_discount,0), IFNULL(p_cost_amount,0), p_payment_type, 'unpaid', 'draft',
            p_description, p_created_by
        );
        SET p_invoice_id = LAST_INSERT_ID();
    END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_create_payment_voucher` (IN `p_branch_id` INT, IN `p_receiver_type` ENUM('supplier','agent','branch','employee','other'), IN `p_receiver_id` INT, IN `p_amount` DECIMAL(15,2), IN `p_currency_id` INT, IN `p_exchange_rate` DECIMAL(15,6), IN `p_cash_bank_account_id` INT, IN `p_party_account_id` INT, IN `p_reference_number` VARCHAR(100), IN `p_description` TEXT, IN `p_created_by` INT, IN `p_cost_center_id` INT, OUT `p_voucher_id` INT, OUT `p_voucher_number` VARCHAR(50))   BEGIN SET p_voucher_number = fn_get_next_sequence('payment'); INSERT INTO financial_transactions ( transaction_number, transaction_date, branch_id, transaction_type, status, entity_type, entity_id, party_account_id, cash_bank_account_id, cost_center_id, currency_id, amount, exchange_rate, reference_number, description, created_by ) VALUES ( p_voucher_number, CURDATE(), p_branch_id, 'payment', 'draft', p_receiver_type, p_receiver_id, p_party_account_id, p_cash_bank_account_id, p_cost_center_id, p_currency_id, p_amount, IFNULL(p_exchange_rate, 1.0), p_reference_number, p_description, p_created_by ); SET p_voucher_id = LAST_INSERT_ID(); END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_create_receipt_voucher` (IN `p_branch_id` INT, IN `p_payer_type` ENUM('customer','agent','branch','other'), IN `p_payer_id` INT, IN `p_amount` DECIMAL(15,2), IN `p_currency_id` INT, IN `p_exchange_rate` DECIMAL(15,6), IN `p_cash_bank_account_id` INT, IN `p_party_account_id` INT, IN `p_reference_number` VARCHAR(100), IN `p_description` TEXT, IN `p_created_by` INT, IN `p_cost_center_id` INT, OUT `p_voucher_id` INT, OUT `p_voucher_number` VARCHAR(50))   BEGIN
        SET p_voucher_number = fn_get_next_sequence('receipt');
