CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_currency_exchange` (IN `p_branch_id` INT, IN `p_from_currency_id` INT, IN `p_from_amount` DECIMAL(15,2), IN `p_to_currency_id` INT, IN `p_to_amount` DECIMAL(15,2), IN `p_exchange_rate` DECIMAL(15,6), IN `p_from_account_id` INT, IN `p_to_account_id` INT, IN `p_notes` TEXT, IN `p_created_by` INT, OUT `p_transaction_id` INT, OUT `p_transaction_number` VARCHAR(50), OUT `p_profit_loss` DECIMAL(15,2))   BEGIN
    DECLARE v_from_acc_type, v_to_acc_type VARCHAR(50);
    
    -- 1. توليد رقم العملية
    SET p_transaction_number = fn_get_next_sequence('EXCH');
    
    -- 2. تحديد أنواع الحسابات (تبسيطاً سنفترض أنها صناديق/بنوك أو حسابات عامة)
    SET v_from_acc_type = 'account';
    SET v_to_acc_type = 'account';
    
    -- 3. حساب الربح/الخسارة (يمكن تعديله لاحقاً حسب منطق العملة الأساسية)
    -- حالياً نعتبره الفرق المباشر إذا كان هناك عمولة مخفية في السعر
    SET p_profit_loss = 0.00; 

    -- 4. إدراج في جدول عمليات الصرف
        transaction_number, transaction_date, from_account_id, from_account_type, 
        from_currency_id, from_amount, to_account_id, to_account_type, 
        to_currency_id, to_amount, profit_loss, exchange_rate, notes, 
        created_by, branch_id
    ) VALUES (
        p_transaction_number, CURDATE(), p_from_account_id, v_from_acc_type,
        p_from_currency_id, p_from_amount, p_to_account_id, v_to_acc_type,
        p_to_currency_id, p_to_amount, p_profit_loss, p_exchange_rate, p_notes,
        p_created_by, p_branch_id
    );
    
    SET p_transaction_id = LAST_INSERT_ID();
    
    -- 5. إنشاء المعاملة المالية الرئيسية (Financial Transaction)
    -- نستخدم نوع 'exchange' للإشارة لعملية صرف
        transaction_number, transaction_date, branch_id, transaction_type, 
        status, currency_id, amount, description, created_by, reference_type, reference_id
    ) VALUES (
        p_transaction_number, CURDATE(), p_branch_id, 'exchange', 
        'draft', p_from_currency_id, p_from_amount, p_notes, p_created_by, 'currency_exchange', p_transaction_id
    );
    
    SET @ft_id = LAST_INSERT_ID();
    
    -- 6. إنشاء قيود اليومية (Journal Lines)
    -- القيد: من حساب المستلم (مدين) إلى حساب الدافع (دائن)
    
    -- الجانب المدين (الاستلام)
        financial_transaction_id, account_id, debit, credit, currency_id, description
    ) VALUES (
        @ft_id, p_to_account_id, p_to_amount, 0, p_to_currency_id, CONCAT('استلام عملة مصرفة - ', p_notes)
    );
    
    -- الجانب الدائن (الدفع)
        financial_transaction_id, account_id, debit, credit, currency_id, description
    ) VALUES (
        @ft_id, p_from_account_id, 0, p_from_amount, p_from_currency_id, CONCAT('دفع عملة للتصريف - ', p_notes)
    );

END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_fix_empty_journal_entries` ()   BEGIN
    DECLARE v_count INT DEFAULT 0;
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    
    
    UPDATE financial_transactions 
    SET status = 'cancelled', 
        cancellation_reason = 'ØªÙ„Ù‚Ø§Ø¦ÙŠ: ØªÙ… Ø§Ù„Ø¥ØµÙ„Ø§Ø­ Ø¨Ø³Ø¨Ø¨ ÙˆØ¬ÙˆØ¯ Ù‚ÙŠÙˆØ¯ ÙØ§Ø±ØºØ© (Zero-Sum)'
    WHERE id IN (
        SELECT DISTINCT financial_transaction_id 
        FROM journal_lines 
        WHERE debit = credit AND debit > 0
    ) AND status = 'posted';
    
    SET v_count = ROW_COUNT();

    
    DELETE FROM journal_lines 
    WHERE debit = credit AND debit > 0;

    COMMIT;
    
    SELECT CONCAT('ØªÙ… Ø¥Ù„ØºØ§Ø¡ ', v_count, ' Ù…Ø¹Ø§Ù…Ù„Ø§Øª ØªØ­ØªÙˆÙŠ Ø¹Ù„Ù‰ Ù‚ÙŠÙˆØ¯ ÙØ§Ø±ØºØ© ÙˆØªÙ†Ø¸ÙŠÙ Ø¬Ø¯ÙˆÙ„ Ø§Ù„Ù‚ÙŠÙˆØ¯.') AS Result;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_handle_entity_account` (IN `p_entity_type` VARCHAR(50), IN `p_entity_id` INT, IN `p_entity_name` VARCHAR(255), OUT `p_account_id` INT)   BEGIN DECLARE v_parent_code VARCHAR(20); DECLARE v_parent_id, v_existing_id INT; DECLARE v_account_code VARCHAR(20); DECLARE v_type ENUM('asset','liability','equity','income','expense'); DECLARE v_normal ENUM('debit','credit'); CASE p_entity_type WHEN 'customer' THEN SET v_parent_code = '1121'; SET v_type = 'asset'; SET v_normal = 'debit'; WHEN 'agent' THEN SET v_parent_code = '1122'; SET v_type = 'asset'; SET v_normal = 'debit'; WHEN 'branch' THEN SET v_parent_code = '1123'; SET v_type = 'asset'; SET v_normal = 'debit'; WHEN 'supplier' THEN SET v_parent_code = '2111'; SET v_type = 'liability'; SET v_normal = 'credit'; WHEN 'employee' THEN SET v_parent_code = '2112'; SET v_type = 'liability'; SET v_normal = 'credit'; ELSE SET v_parent_code = NULL; END CASE; IF v_parent_code IS NOT NULL THEN SELECT id INTO v_parent_id FROM unified_accounts WHERE account_code = v_parent_code; SET v_account_code = CONCAT(v_parent_code, LPAD(p_entity_id, 4, '0')); SELECT id INTO v_existing_id FROM unified_accounts WHERE account_code = v_account_code; IF v_existing_id IS NULL THEN INSERT INTO unified_accounts (parent_id, account_code, account_name_ar, account_type, normal_balance) VALUES (v_parent_id, v_account_code, p_entity_name, v_type, v_normal); SET p_account_id = LAST_INSERT_ID(); ELSE SET p_account_id = v_existing_id; END IF; END IF; END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_invoice` (IN `p_invoice_id` INT, IN `p_posted_by` INT)   PROC_BODY: BEGIN
    DECLARE v_invoice_category ENUM('sales','purchase');
