    ELSE
        VALUES (v_transaction_id, v_cost_account_id, v_net_amount, 0, v_currency_id, CONCAT('ØªÙƒÙ„ÙØ© Ø®Ø¯Ù…Ø§Øª - ÙØ§ØªÙˆØ±Ø© ', v_invoice_number));

        IF v_amount_received >= v_net_amount THEN
            VALUES (v_transaction_id, v_account_id, 0, v_net_amount, v_currency_id, CONCAT('Ø³Ø¯Ø§Ø¯ Ù†Ù‚Ø¯ÙŠ ÙƒØ§Ù…Ù„ - ÙØ§ØªÙˆØ±Ø© ', v_invoice_number));
        ELSEIF v_amount_received = 0 THEN
            VALUES (v_transaction_id, v_account_id, 0, v_net_amount, v_currency_id, CONCAT('Ø§Ø³ØªØ­Ù‚Ø§Ù‚ Ù…ÙˆØ±Ø¯ Ø¢Ø¬Ù„ - ÙØ§ØªÙˆØ±Ø© ', v_invoice_number));
        ELSE
            SET v_acc_exists = CASE WHEN v_payment_type = 'bank_transfer' THEN v_bank_account_id ELSE v_cash_account_id END;
            VALUES (v_transaction_id, v_acc_exists, 0, v_amount_received, v_currency_id, CONCAT('Ø³Ø¯Ø§Ø¯ Ø¬Ø²Ø¦ÙŠ - ÙØ§ØªÙˆØ±Ø© ', v_invoice_number));
            
            VALUES (v_transaction_id, v_account_id, 0, (v_net_amount - v_amount_received), v_currency_id, CONCAT('Ù…ØªØ¨Ù‚ÙŠ Ø§Ø³ØªØ­Ù‚Ø§Ù‚ Ù„Ù„Ù…ÙˆØ±Ø¯ - ÙØ§ØªÙˆØ±Ø© ', v_invoice_number));
        END IF;
    END IF;

    UPDATE invoices SET invoice_status = 'posted', posted_at = NOW(), posted_by = p_posted_by WHERE id = p_invoice_id;
    CALL sp_update_account_balances(v_transaction_id);
    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_invoice_v2` (IN `p_invoice_id` INT, IN `p_user_id` INT)   BEGIN
    DECLARE v_current_status VARCHAR(20);
    DECLARE v_ft_id INT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    IF fn_check_permission(p_user_id, 'invoice_post') = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ليس لديك صلاحية ترحيل الفواتير';
    END IF;
    
    START TRANSACTION;
    
    SELECT invoice_status INTO v_current_status FROM invoices WHERE id = p_invoice_id FOR UPDATE;
    
    IF v_current_status = 'draft' THEN
        CALL sp_post_invoice(p_invoice_id, p_user_id);
    ELSEIF v_current_status = 'posted' THEN
        SELECT id INTO v_ft_id FROM financial_transactions 
        WHERE reference_id = p_invoice_id AND reference_type = 'invoice' LIMIT 1;
        
        IF v_ft_id IS NOT NULL THEN
            SELECT v_ft_id, account_id, cost_center_id, credit, debit, currency_id,
                   CONCAT('عكس قيد فاتورة - بواسطة ', p_user_id, ' - ', NOW())
            FROM journal_lines WHERE financial_transaction_id = v_ft_id;
            
            CALL sp_update_account_balances(v_ft_id);
            UPDATE financial_transactions SET status = 'cancelled' WHERE id = v_ft_id;
        END IF;
        
        UPDATE invoices SET invoice_status = 'cancelled' WHERE id = p_invoice_id;
    ELSE
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'حالة الفاتورة لا تسمح بالإجراء';
    END IF;
    
    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_payment_voucher` (IN `p_transaction_id` INT, IN `p_posted_by` INT, IN `p_invoice_allocations` JSON)   BEGIN
    DECLARE v_amount          DECIMAL(18,4);
    DECLARE v_currency_id     INT;
    DECLARE v_cash_account_id INT;
    DECLARE v_party_account_id INT;
    DECLARE v_status          VARCHAR(50);
    DECLARE v_inv_id          INT;
    DECLARE v_alloc_amount    DECIMAL(18,4);
    DECLARE done              INT DEFAULT FALSE;

    -- Cursor for existing allocations if JSON is NULL
    DECLARE cur_alloc CURSOR FOR 
        SELECT invoice_id, allocated_amount 
        FROM payment_allocations 
        WHERE financial_transaction_id = p_transaction_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    -- Basic data retrieval
    SELECT amount, currency_id, cash_bank_account_id, party_account_id, status  
    INTO v_amount, v_currency_id, v_cash_account_id, v_party_account_id, v_status
    FROM financial_transactions 
    WHERE id = p_transaction_id;

    -- Check status
    IF v_status != 'draft' AND v_status != 'cancelled' THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'السند ليس في حالة مسودة أو ملغي ولا يمكن ترحيله';
    END IF;

    -- Clear existing journal lines to avoid duplicates
    DELETE FROM journal_lines WHERE financial_transaction_id = p_transaction_id;

    -- Insert Journal Lines: Debit Party, Credit Cash/Bank
    VALUES (p_transaction_id, v_party_account_id, v_currency_id, v_amount, 0, 
            CONCAT('ترحيل سند صرف رقم #', p_transaction_id));

    VALUES (p_transaction_id, v_cash_account_id, v_currency_id, 0, v_amount, 
            CONCAT('ترحيل سند صرف رقم #', p_transaction_id));

    -- Update Account Balances
    CALL sp_update_account_balances(p_transaction_id);

    -- Update Voucher Status FIRST so recalculation sees it as posted
    UPDATE financial_transactions 
    SET status = 'posted', 
        posted_at = NOW(), 
        posted_by = p_posted_by 
    WHERE id = p_transaction_id;

    -- Handle Invoice Allocations
    IF p_invoice_allocations IS NOT NULL THEN
        -- If new allocations provided via JSON, replace existing ones
        DELETE FROM payment_allocations WHERE financial_transaction_id = p_transaction_id;
        
        SET @i = 0;
        WHILE @i < JSON_LENGTH(p_invoice_allocations) DO
            SET @inv_id = JSON_EXTRACT(p_invoice_allocations, CONCAT('$[', @i, '].invoice_id'));
            SET @alloc = JSON_EXTRACT(p_invoice_allocations, CONCAT('$[', @i, '].amount'));

            VALUES (p_transaction_id, @inv_id, @alloc);
            
            CALL sp_recalculate_invoice_payment(@inv_id);
            SET @i = @i + 1;
        END WHILE;
    ELSE
        -- If no JSON provided, just recalculate based on existing allocations
        OPEN cur_alloc;
        pay_loop: LOOP
            FETCH cur_alloc INTO v_inv_id, v_alloc_amount;
            IF done THEN LEAVE pay_loop; END IF;
            CALL sp_recalculate_invoice_payment(v_inv_id);
        END LOOP;
        CLOSE cur_alloc;
    END IF;

END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_payment_voucher_v2` (IN `p_voucher_id` INT, IN `p_user_id` INT)   BEGIN
    DECLARE v_current_status VARCHAR(20);
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    IF fn_check_permission(p_user_id, 'voucher_post') = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'ليس لديك صلاحية الترحيل';
    END IF;
    
    START TRANSACTION;
    
    SELECT status INTO v_current_status
    FROM financial_transactions
    WHERE id = p_voucher_id FOR UPDATE;
    
    IF v_current_status = 'draft' OR v_current_status = 'cancelled' THEN
        CALL sp_post_payment_voucher(p_voucher_id, p_user_id, NULL);
    ELSEIF v_current_status = 'posted' THEN
        SELECT p_voucher_id, account_id, cost_center_id, credit, debit, currency_id,
               CONCAT('عكس قيد - بواسطة المستخدم ', p_user_id, ' - ', NOW())
        FROM journal_lines WHERE financial_transaction_id = p_voucher_id;
        
        CALL sp_update_account_balances(p_voucher_id);
        
        UPDATE financial_transactions
        SET status = 'cancelled', cancelled_at = NOW(), cancelled_by = p_user_id,
            cancellation_reason = 'إلغاء ترحيل يدوي'
        WHERE id = p_voucher_id;
    ELSE
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'حالة المعاملة لا تسمح بالإجراء';
    END IF;
    
    COMMIT;
END$$

