CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_rebuild_balances` ()   BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    
    START TRANSACTION;
    UPDATE account_balances_unified SET current_balance = 0, current_balance_base = 0;
    
    SELECT jl.account_id, jl.currency_id, 
        SUM(CASE WHEN ua.normal_balance = 'debit' THEN jl.debit - jl.credit ELSE jl.credit - jl.debit END),
        SUM(CASE WHEN ua.normal_balance = 'debit' THEN jl.debit - jl.credit ELSE jl.credit - jl.debit END),
        NOW() 
    FROM journal_lines jl 
    JOIN financial_transactions ft ON jl.financial_transaction_id = ft.id 
    JOIN unified_accounts ua ON jl.account_id = ua.id
    WHERE ft.status = 'posted' 
    GROUP BY jl.account_id, jl.currency_id
    ON DUPLICATE KEY UPDATE current_balance = VALUES(current_balance), current_balance_base = VALUES(current_balance_base), last_updated = VALUES(last_updated); 
    
    COMMIT; 
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_recalculate_invoice_payment` (IN `p_invoice_id` INT)   BEGIN
    DECLARE v_total_received DECIMAL(18,4) DEFAULT 0;
    DECLARE v_net_amount     DECIMAL(18,4) DEFAULT 0;
    DECLARE v_new_status     VARCHAR(50);

    SELECT COALESCE(SUM(pa.allocated_amount), 0)
    INTO v_total_received
    FROM payment_allocations pa
    JOIN financial_transactions ft ON pa.financial_transaction_id = ft.id
    WHERE pa.invoice_id = p_invoice_id
      AND ft.status = 'posted';

    SELECT COALESCE(net_amount, 0)
    INTO v_net_amount
    FROM invoices
    WHERE id = p_invoice_id;

    IF v_total_received <= 0 THEN
        SET v_new_status = 'unpaid';
    ELSEIF v_total_received < v_net_amount THEN
        SET v_new_status = 'partial';
    ELSE
        SET v_new_status = 'fully_paid';   -- ✅ إصلاح: كان 'paid' والصحيح 'fully_paid'
    END IF;

    UPDATE invoices
    SET amount_received = v_total_received,
        payment_status  = v_new_status,
        updated_at      = NOW()
    WHERE id = p_invoice_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_account_balances` (IN `p_transaction_id` INT)   BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE v_account_id INT;
    DECLARE v_debit DECIMAL(18,2);
    DECLARE v_credit DECIMAL(18,2);
    DECLARE v_currency_id INT;
    DECLARE v_normal_balance ENUM('debit','credit');
    
    DECLARE cur1 CURSOR FOR 
        SELECT jl.account_id, jl.debit, jl.credit, jl.currency_id, ua.normal_balance
        FROM journal_lines jl
        JOIN unified_accounts ua ON jl.account_id = ua.id
        WHERE jl.financial_transaction_id = p_transaction_id;
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    OPEN cur1;
    
    read_loop: LOOP
        FETCH cur1 INTO v_account_id, v_debit, v_credit, v_currency_id, v_normal_balance;
        IF done THEN LEAVE read_loop; END IF;
        
        VALUES (v_account_id, v_currency_id, 0, 0);
        
        IF v_normal_balance = 'debit' THEN
            UPDATE account_balances_unified 
            SET current_balance = current_balance + (v_debit - v_credit)
            WHERE account_id = v_account_id AND currency_id = v_currency_id;
        ELSE
            UPDATE account_balances_unified 
            SET current_balance = current_balance + (v_credit - v_debit)
            WHERE account_id = v_account_id AND currency_id = v_currency_id;
        END IF;
    END LOOP;
    
    CLOSE cur1;
END$$

--
-- Functions
--
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_check_permission` (`p_user_id` INT, `p_permission_code` VARCHAR(50)) RETURNS TINYINT(1) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE v_has_permission TINYINT(1) DEFAULT 0;
    
    -- فحص إذا كان المستخدم مدير عام أو مطور
    IF EXISTS (
        SELECT 1 FROM users u 
        JOIN roles r ON u.role_id = r.id 
        WHERE u.id = p_user_id AND r.name IN ('admin', 'developer')
    ) THEN
        RETURN 1;
    END IF;
    
    -- فحص الصلاحية المحددة
    SELECT 1 INTO v_has_permission
    FROM role_permissions_unified rp
    JOIN unified_permissions p ON rp.permission_id = p.id
    JOIN users u ON u.role_id = rp.role_id
    WHERE u.id = p_user_id AND p.permission_code = p_permission_code
    LIMIT 1;
    
    RETURN IFNULL(v_has_permission, 0);
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_convert_currency` (`p_amount` DECIMAL(15,2), `p_from_currency_id` INT, `p_to_currency_id` INT) RETURNS DECIMAL(15,2) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE v_from_rate, v_to_rate DECIMAL(15,6);
    DECLARE v_base_amount DECIMAL(15,2);
    
    -- إذا كانت نفس العملة
    IF p_from_currency_id = p_to_currency_id THEN
        RETURN p_amount;
    END IF;
    
    -- جلب أسعار الصرف (نسبة للعملة الأساسية)
    SELECT exchange_rate INTO v_from_rate FROM currencies WHERE id = p_from_currency_id;
    SELECT exchange_rate INTO v_to_rate FROM currencies WHERE id = p_to_currency_id;
    
    -- تحويل للعملة الأساسية ثم للعملة المستهدفة
    SET v_base_amount = p_amount * IFNULL(v_from_rate, 1.0);
    RETURN v_base_amount / IFNULL(v_to_rate, 1.0);
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_convert_to_base_currency` (`p_amount` DECIMAL(15,2), `p_currency_id` INT) RETURNS DECIMAL(15,2) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE v_exchange_rate DECIMAL(15,6);
    DECLARE v_is_default TINYINT;
    
    SELECT exchange_rate, is_default INTO v_exchange_rate, v_is_default 
    FROM currencies WHERE id = p_currency_id;
    
    IF v_is_default = 1 THEN 
        RETURN p_amount; 
    END IF;
    
    RETURN ROUND(p_amount * IFNULL(v_exchange_rate, 1.0), 2);
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_get_exchange_rate` (`p_currency_id` INT, `p_type` VARCHAR(10)) RETURNS DECIMAL(15,6) DETERMINISTIC READS SQL DATA BEGIN
    DECLARE v_rate DECIMAL(15,6);
    IF p_type = 'buy' THEN
        SELECT exchange_rate_buy INTO v_rate FROM currencies WHERE id = p_currency_id;
    ELSE
        SELECT exchange_rate_sell INTO v_rate FROM currencies WHERE id = p_currency_id;
    END IF;
    RETURN IFNULL(v_rate, 1.000000);
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_get_next_sequence` (`p_sequence_name` VARCHAR(50)) RETURNS VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci DETERMINISTIC READS SQL DATA BEGIN 
        DECLARE v_prefix VARCHAR(10); 
        DECLARE v_year VARCHAR(4); 
        DECLARE v_last_number INT; 
        SET v_year = DATE_FORMAT(CURDATE(), '%y'); 
        CASE p_sequence_name 
            WHEN 'invoice' THEN SET v_prefix = CONCAT('INV-', v_year, '-'); 
            WHEN 'receipt' THEN SET v_prefix = CONCAT('RCT-', v_year, '-'); 
            WHEN 'payment' THEN SET v_prefix = CONCAT('PMT-', v_year, '-'); 
            WHEN 'journal' THEN SET v_prefix = CONCAT('JRN-', v_year, '-'); 
            ELSE SET v_prefix = CONCAT(p_sequence_name, '-'); 
        END CASE; 
        SET v_last_number = 0; 
        IF p_sequence_name = 'invoice' THEN 
            SELECT MAX(CAST(SUBSTRING(invoice_number, LENGTH(v_prefix)+1) AS UNSIGNED)) INTO v_last_number FROM invoices WHERE invoice_number LIKE CONCAT(v_prefix, '%'); 
        ELSE 
            SELECT MAX(CAST(SUBSTRING(transaction_number, LENGTH(v_prefix)+1) AS UNSIGNED)) INTO v_last_number FROM financial_transactions WHERE transaction_number LIKE CONCAT(v_prefix, '%'); 
        END IF; 
        SET v_last_number = IFNULL(v_last_number, 0) + 1; 
        RETURN CONCAT(v_prefix, LPAD(v_last_number, 5, '0')); 
    END$$

DELIMITER ;

