--
-- بنية الجدول `account_balances_unified`
--

CREATE TABLE `account_balances_unified` (
  `id` int(11) NOT NULL,
  `account_id` int(11) NOT NULL,
  `branch_id` int(11) DEFAULT NULL,
  `currency_id` int(11) NOT NULL,
  `currency_code` varchar(10) DEFAULT NULL,
  `opening_balance` decimal(15,2) DEFAULT 0.00,
  `current_balance` decimal(18,2) DEFAULT NULL,
  `current_balance_base` decimal(18,2) DEFAULT 0.00,
  `credit_limit` decimal(18,2) DEFAULT 0.00,
  `debit_limit` decimal(18,2) DEFAULT 0.00,
  `is_frozen` tinyint(1) DEFAULT 0,
  `last_updated` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `cost_center_id` int(11) DEFAULT NULL,
  `opening_balance_base` decimal(18,2) DEFAULT 0.00
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- إرجاع أو استيراد بيانات الجدول `account_balances_unified`
--


--
-- القوادح `account_balances_unified`
--
DELIMITER $$
CREATE TRIGGER `trg_insert_balance_base` BEFORE INSERT ON `account_balances_unified` FOR EACH ROW BEGIN
            DECLARE v_rate DECIMAL(15,6);
            IF NEW.current_balance = 0 THEN
                SET NEW.current_balance_base = 0;
            ELSE
                SELECT exchange_rate INTO v_rate FROM currencies WHERE id = NEW.currency_id;
                SET NEW.current_balance_base = NEW.current_balance * IFNULL(v_rate, 1.0);
            END IF;
            
            IF NEW.opening_balance = 0 THEN
                SET NEW.opening_balance_base = 0;
            ELSE
                IF v_rate IS NULL THEN
                    SELECT exchange_rate INTO v_rate FROM currencies WHERE id = NEW.currency_id;
                END IF;
                SET NEW.opening_balance_base = NEW.opening_balance * IFNULL(v_rate, 1.0);
            END IF;
        END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_update_balance_base` BEFORE UPDATE ON `account_balances_unified` FOR EACH ROW BEGIN
            DECLARE v_rate DECIMAL(15,6);
            IF NEW.current_balance = 0 THEN
                SET NEW.current_balance_base = 0;
            ELSE
                SELECT exchange_rate INTO v_rate FROM currencies WHERE id = NEW.currency_id;
                SET NEW.current_balance_base = NEW.current_balance * IFNULL(v_rate, 1.0);
            END IF;
            
            IF NEW.opening_balance = 0 THEN
                SET NEW.opening_balance_base = 0;
            ELSE
                IF v_rate IS NULL THEN
                    SELECT exchange_rate INTO v_rate FROM currencies WHERE id = NEW.currency_id;
                END IF;
                SET NEW.opening_balance_base = NEW.opening_balance * IFNULL(v_rate, 1.0);
            END IF;
        END
$$
DELIMITER ;

