--
-- القوادح `employees`
--
DELIMITER $$
CREATE TRIGGER `trg_after_employee_insert` AFTER INSERT ON `employees` FOR EACH ROW BEGIN
    DECLARE v_parent_salaf_id INT;
    DECLARE v_parent_ahda_id INT;
    DECLARE v_next_salaf_code VARCHAR(50);
    DECLARE v_next_ahda_code VARCHAR(50);
    DECLARE v_salaf_account_name VARCHAR(255);
    DECLARE v_ahda_account_name VARCHAR(255);

    
    SELECT id INTO v_parent_salaf_id FROM unified_accounts WHERE account_code = '11301';
    SELECT id INTO v_parent_ahda_id FROM unified_accounts WHERE account_code = '11302';

    
    SELECT CONCAT('11301', LPAD(COALESCE(MAX(CAST(SUBSTRING(account_code, 6) AS UNSIGNED)), 0) + 1, 3, '0')) 
    INTO v_next_salaf_code 
    FROM unified_accounts 
    WHERE account_code LIKE '11301%' AND LENGTH(account_code) = 9;

    SELECT CONCAT('11302', LPAD(COALESCE(MAX(CAST(SUBSTRING(account_code, 6) AS UNSIGNED)), 0) + 1, 3, '0')) 
    INTO v_next_ahda_code 
    FROM unified_accounts 
    WHERE account_code LIKE '11302%' AND LENGTH(account_code) = 9;

    
    SET v_salaf_account_name = CONCAT('???????? ???????????? / ', NEW.full_name);
    SET v_ahda_account_name = CONCAT('???????? ???????????? / ', NEW.full_name);

    
        account_code, account_name_ar, account_type, normal_balance,
        parent_id, account_status, created_at, entity_type, entity_id
    ) VALUES (
        v_next_salaf_code, v_salaf_account_name, 'asset', 'debit',
        v_parent_salaf_id, 'active', NOW(), 'employee', NEW.id
    );

    
        account_code, account_name_ar, account_type, normal_balance,
        parent_id, account_status, created_at, entity_type, entity_id
    ) VALUES (
        v_next_ahda_code, v_ahda_account_name, 'asset', 'debit',
        v_parent_ahda_id, 'active', NOW(), 'employee', NEW.id
    );

    
    UPDATE employees 
    SET 
        salaf_account_id = LAST_INSERT_ID() - 1,
        ahda_account_id = LAST_INSERT_ID()
    WHERE id = NEW.id;
END
$$
DELIMITER ;

