--
-- إرجاع أو استيراد بيانات الجدول `invoices`
--


--
-- القوادح `invoices`
--
DELIMITER $$
CREATE TRIGGER `trg_invoices_net_amount_before_insert` BEFORE INSERT ON `invoices` FOR EACH ROW BEGIN
    SET NEW.net_amount = COALESCE(NEW.total_amount, 0) - COALESCE(NEW.discount, 0);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_invoices_net_amount_before_update` BEFORE UPDATE ON `invoices` FOR EACH ROW BEGIN
    IF OLD.total_amount <> NEW.total_amount OR OLD.discount <> NEW.discount THEN
        SET NEW.net_amount = COALESCE(NEW.total_amount, 0) - COALESCE(NEW.discount, 0);
    END IF;
END
$$
DELIMITER ;

