--
-- بنية الجدول `journal_lines`
--

CREATE TABLE `journal_lines` (
  `id` int(11) NOT NULL,
  `branch_id` int(11) DEFAULT NULL,
  `financial_transaction_id` int(11) NOT NULL,
  `account_id` int(11) NOT NULL,
  `cost_center_id` int(11) DEFAULT NULL,
  `debit` decimal(15,2) DEFAULT 0.00,
  `credit` decimal(15,2) DEFAULT 0.00,
  `currency_id` int(11) NOT NULL,
  `description` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- إرجاع أو استيراد بيانات الجدول `journal_lines`
--


--
-- القوادح `journal_lines`
--
DELIMITER $$
CREATE TRIGGER `trg_journal_lines_after_delete` AFTER DELETE ON `journal_lines` FOR EACH ROW BEGIN
    DECLARE v_exchange_rate DECIMAL(18,6);
    DECLARE v_amount DECIMAL(18,2);
    
    SELECT exchange_rate INTO v_exchange_rate FROM currencies WHERE id = OLD.currency_id;
    IF v_exchange_rate IS NULL THEN SET v_exchange_rate = 1.0; END IF;
    
    SET v_amount = OLD.debit - OLD.credit;
    
    UPDATE account_balances_unified 
    SET current_balance = current_balance - v_amount,
        current_balance_base = current_balance_base - (v_amount * v_exchange_rate),
        last_updated = NOW()
    WHERE account_id = OLD.account_id AND currency_id = OLD.currency_id AND (branch_id = OLD.branch_id OR (branch_id IS NULL AND OLD.branch_id IS NULL));
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_journal_lines_after_insert` AFTER INSERT ON `journal_lines` FOR EACH ROW BEGIN
    DECLARE v_exchange_rate DECIMAL(18,6);
    DECLARE v_amount DECIMAL(18,2);
    DECLARE v_amount_base DECIMAL(18,2);
    
    SELECT exchange_rate INTO v_exchange_rate FROM currencies WHERE id = NEW.currency_id;
    IF v_exchange_rate IS NULL THEN SET v_exchange_rate = 1.0; END IF;
    
    SET v_amount = NEW.debit - NEW.credit;
    SET v_amount_base = v_amount * v_exchange_rate;
    
    VALUES (NEW.account_id, NEW.branch_id, NEW.currency_id, 0, v_amount, v_amount_base)
    ON DUPLICATE KEY UPDATE 
        current_balance = current_balance + v_amount,
        current_balance_base = current_balance_base + v_amount_base,
        last_updated = NOW();
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_journal_lines_after_update` AFTER UPDATE ON `journal_lines` FOR EACH ROW BEGIN
    DECLARE v_old_rate DECIMAL(18,6);
    DECLARE v_new_rate DECIMAL(18,6);
    DECLARE v_old_amount DECIMAL(18,2);
    DECLARE v_new_amount DECIMAL(18,2);
    
    
    SELECT exchange_rate INTO v_old_rate FROM currencies WHERE id = OLD.currency_id;
    IF v_old_rate IS NULL THEN SET v_old_rate = 1.0; END IF;
    SET v_old_amount = OLD.debit - OLD.credit;
    
    UPDATE account_balances_unified 
    SET current_balance = current_balance - v_old_amount,
        current_balance_base = current_balance_base - (v_old_amount * v_old_rate)
    WHERE account_id = OLD.account_id AND currency_id = OLD.currency_id AND (branch_id = OLD.branch_id OR (branch_id IS NULL AND OLD.branch_id IS NULL));
    
    
    SELECT exchange_rate INTO v_new_rate FROM currencies WHERE id = NEW.currency_id;
    IF v_new_rate IS NULL THEN SET v_new_rate = 1.0; END IF;
    SET v_new_amount = NEW.debit - NEW.credit;
    
    VALUES (NEW.account_id, NEW.branch_id, NEW.currency_id, 0, v_new_amount, v_new_amount * v_new_rate)
    ON DUPLICATE KEY UPDATE 
        current_balance = current_balance + v_new_amount,
        current_balance_base = current_balance_base + (v_new_amount * v_new_rate),
        last_updated = NOW();
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_journal_lines_branch` BEFORE INSERT ON `journal_lines` FOR EACH ROW BEGIN
    IF NEW.branch_id IS NULL THEN
        SET NEW.branch_id = (SELECT branch_id FROM financial_transactions WHERE id = NEW.financial_transaction_id);
    END IF;
    IF NEW.branch_id IS NULL THEN
        SET NEW.branch_id = 1;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_journal_lines_branch_update` BEFORE UPDATE ON `journal_lines` FOR EACH ROW SET NEW.branch_id = COALESCE(NEW.branch_id, (SELECT branch_id FROM financial_transactions WHERE id = NEW.financial_transaction_id))
$$
DELIMITER ;

